/**
 * Eval report exporter extension contract.
 *
 * A single `EvalReportExporterRegistry` implementation lives in the contract
 * registry under {@link EvalReportExporterRegistryName}. Vendor extensions
 * resolve that registry during setup() and register one exporter each.
 *
 * @module extensions/eval/eval-report-exporter
 */
import { assertRegistrationMethod, captureRegistrationId } from "../runtime-validation.js";
import { describeThrownValue } from "../safe-value.js";
/** Contract name used for `resolve()` / `provide()`. */
export const EvalReportExporterRegistryName = "EvalReportExporterRegistry";
/** Sentinel used when record payload fields are removed for external export. */
export const EvalReportRedactedValue = "[redacted]";
function filterMetadata(metadata, allowlist) {
    if (!allowlist || allowlist.length === 0)
        return {};
    const allowed = new Set(allowlist);
    return Object.fromEntries(Object.entries(metadata).filter(([key]) => allowed.has(key)));
}
function redactRecord(record, redaction) {
    const redacted = {
        ...record,
        input: redaction.includeInputs ? record.input : EvalReportRedactedValue,
        ...(Object.hasOwn(record, "executionInput")
            ? {
                executionInput: redaction.includeInputs ? record.executionInput : EvalReportRedactedValue,
            }
            : {}),
        output: redaction.includeOutputs ? record.output : EvalReportRedactedValue,
        metadata: filterMetadata(record.metadata, redaction.metadataAllowlist),
        trace: redaction.includeTraces ? record.trace : { events: [], toolCalls: [] },
        ...(record.metrics ? { metrics: redactMetricResults(record.metrics, redaction) } : {}),
        ...(record.checks ? { checks: redactMetricResults(record.checks, redaction) } : {}),
    };
    if (Object.hasOwn(record, "reference")) {
        redacted.reference = redaction.includeReferences ? record.reference : EvalReportRedactedValue;
    }
    if (Object.hasOwn(record, "retrievedContext")) {
        redacted.retrievedContext = redaction.includeRetrievedContext ? record.retrievedContext : [];
    }
    if (Object.hasOwn(record, "citations")) {
        redacted.citations = redaction.includeCitations ? record.citations : [];
    }
    return redacted;
}
function redactMetricResults(results, redaction) {
    return results.map((result) => {
        const redacted = { ...result };
        if (!redaction.includeMetricExplanations) {
            delete redacted.explanation;
        }
        if (!redaction.includeMetricEvidence) {
            delete redacted.evidence;
            // The label spells out the metric's configured parameter: the asserted tool name, expected
            // text, or regex. That is the same class of detail as `evidence`, so it leaves on the same
            // terms. CLI output is unaffected; this boundary only governs what reaches an exporter.
            delete redacted.label;
        }
        return redacted;
    });
}
function redactGateFailures(gateFailures, redaction) {
    return gateFailures.map((failure) => {
        const redacted = { ...failure };
        if (!redaction.includeMetricExplanations) {
            delete redacted.explanation;
        }
        if (!redaction.includeMetricEvidence) {
            delete redacted.evidence;
        }
        return redacted;
    });
}
function redactSummary(summary, redaction) {
    const redacted = { ...summary };
    if (!redaction.includeMetricEvidence) {
        redacted.metrics = summary.metrics.map((metric) => {
            const redactedMetric = { ...metric };
            delete redactedMetric.label;
            return redactedMetric;
        });
    }
    // Every gate failure copies the blocking result's explanation and evidence verbatim, so citation
    // labels and retrieved-source labels reach the summary too. They leave on the same terms as the
    // record-level metric they came from.
    if (summary.gateFailures) {
        redacted.gateFailures = redactGateFailures(summary.gateFailures, redaction);
    }
    return redacted;
}
function cloneRedaction(redaction) {
    if (!redaction)
        return undefined;
    return {
        ...redaction,
        ...(redaction.metadataAllowlist ? { metadataAllowlist: [...redaction.metadataAllowlist] } : {}),
    };
}
function redactDatasetMetadata(dataset, redaction) {
    const redactedDataset = { ...dataset };
    if (!redaction.includeDatasetPath)
        delete redactedDataset.path;
    if (!redaction.includeDatasetHash)
        delete redactedDataset.hash;
    return redactedDataset;
}
function redactEvalReportExportContext(context, redaction) {
    const exportContext = {
        ...context,
        ...(context.tags ? { tags: [...context.tags] } : {}),
        ...(context.trace ? { trace: { ...context.trace } } : {}),
        ...(context.metadata
            ? { metadata: filterMetadata(context.metadata, redaction.metadataAllowlist) }
            : {}),
    };
    const redactionCopy = cloneRedaction(redaction);
    if (context.redaction && redactionCopy) {
        exportContext.redaction = redactionCopy;
    }
    else {
        delete exportContext.redaction;
    }
    return exportContext;
}
/** Create an eval report copy with external-export redaction applied. */
export function redactEvalReportForExport(report, redaction = {}) {
    const cloned = structuredClone(report);
    return {
        ...cloned,
        ...(cloned.dataset ? { dataset: redactDatasetMetadata(cloned.dataset, redaction) } : {}),
        summary: redactSummary(cloned.summary, redaction),
        records: cloned.records.map((record) => redactRecord(record, redaction)),
    };
}
class EvalReportExporterRegistryImpl {
    exporters = new Map();
    register(exporter) {
        const exporterId = captureRegistrationId(exporter, "EvalReportExporter");
        assertRegistrationMethod(exporter, "EvalReportExporter", "export");
        if (this.exporters.has(exporterId)) {
            return;
        }
        this.exporters.set(exporterId, exporter);
    }
    unregister(id) {
        this.exporters.delete(id);
    }
    get(id) {
        return this.exporters.get(id);
    }
    require(id) {
        const exporter = this.exporters.get(id);
        if (exporter)
            return exporter;
        const known = [...this.exporters.keys()].join(", ") || "(none)";
        throw new Error(`No EvalReportExporter registered for "${id}". Known exporters: ${known}.`);
    }
    has(id) {
        return this.exporters.has(id);
    }
    list() {
        return [...this.exporters.values()];
    }
    async export(report, context = {}) {
        const results = [];
        const redaction = cloneRedaction(context.redaction) ?? {};
        const exporters = [...this.exporters.entries()];
        for (const [exporterId, exporter] of exporters) {
            try {
                const sanitizedReport = redactEvalReportForExport(report, redaction);
                const exportContext = redactEvalReportExportContext(context, redaction);
                const receipt = await exporter.export(sanitizedReport, exportContext);
                const result = { exporterId, ok: true };
                if (receipt !== undefined)
                    result.receipt = receipt;
                results.push(result);
            }
            catch (error) {
                results.push({
                    exporterId,
                    ok: false,
                    error: describeThrownValue(error),
                });
            }
        }
        return results;
    }
}
/** Create an eval report exporter registry. */
export function createEvalReportExporterRegistry() {
    return new EvalReportExporterRegistryImpl();
}
